import os
import subprocess
import re
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Configuration
ALLOWED_REPOS = ['main-app', 'frontend', 'backend-api', 'data-pipeline']
BUILD_DIR = os.environ.get('BUILD_DIR', '/tmp/builds')
GIT_BASE = os.environ.get('GIT_BASE', 'https://internal-git.corp.example.com')

def sanitize_branch(branch):
    """Sanitize branch name to prevent obvious injection."""
    # Allow alphanumeric, hyphens, underscores, slashes, dots
    if not re.match(r'^[a-zA-Z0-9._/\-]+$', branch):
        return None
    return branch

def validate_repo(repo):
    """Ensure repo is in allowed list."""
    return repo in ALLOWED_REPOS

@app.route('/api/build', methods=['POST'])
def trigger_build():
    """Trigger a build for a given repo and branch."""
    data = request.get_json()
    if not data:
        abort(400, 'JSON body required')

    repo = data.get('repo', '')
    branch = data.get('branch', 'main')
    build_args = data.get('build_args', '')

    if not validate_repo(repo):
        return jsonify({'error': 'Invalid repository'}), 403

    branch = sanitize_branch(branch)
    if branch is None:
        return jsonify({'error': 'Invalid branch name'}), 400

    # Construct build command
    repo_url = f"{GIT_BASE}/{repo}.git"
    work_dir = os.path.join(BUILD_DIR, repo, branch.replace('/', '_'))
    os.makedirs(work_dir, exist_ok=True)

    # Clone and build - build_args passed to make for custom targets
    clone_cmd = f"git clone --branch {branch} --single-branch {repo_url} {work_dir}/src 2>&1"
    build_cmd = f"cd {work_dir}/src && make build {build_args} 2>&1"

    try:
        clone_result = subprocess.run(
            clone_cmd, shell=True, capture_output=True, text=True, timeout=120
        )
        if clone_result.returncode != 0:
            return jsonify({
                'status': 'clone_failed',
                'output': clone_result.stdout + clone_result.stderr
            }), 500

        build_result = subprocess.run(
            build_cmd, shell=True, capture_output=True, text=True, timeout=300
        )

        return jsonify({
            'status': 'success' if build_result.returncode == 0 else 'build_failed',
            'output': build_result.stdout[-2000:],
            'errors': build_result.stderr[-2000:]
        })
    except subprocess.TimeoutExpired:
        return jsonify({'status': 'timeout'}), 504

@app.route('/api/builds', methods=['GET'])
def list_builds():
    """List recent builds."""
    builds = []
    if os.path.exists(BUILD_DIR):
        for repo in os.listdir(BUILD_DIR):
            repo_path = os.path.join(BUILD_DIR, repo)
            if os.path.isdir(repo_path):
                for branch_dir in os.listdir(repo_path):
                    builds.append({'repo': repo, 'branch': branch_dir})
    return jsonify({'builds': builds[:50]})

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
